import { build } from "esbuild";
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
const root = new URL("../", import.meta.url);
const result = await build({
  entryPoints: [fileURLToPath(new URL("src/v2/passkeys/browser.ts", root))],
  bundle: true,
  platform: "browser",
  format: "iife",
  target: ["es2022"],
  minify: true,
  write: false,
});
writeFileSync(
  new URL("src/v2/passkeys/browser.generated.ts", root),
  "// Generated by scripts/build-passkey-page.mjs\nexport const passkeyScript=" +
    JSON.stringify(result.outputFiles[0].text) +
    ";\n",
);
